const { status, afterStart, beforeEnd } = $.input;
const params = {};
if (status) params.status = status;
if (afterStart) params['afterStart'] = afterStart;
if (beforeEnd) params['beforeEnd'] = beforeEnd;
return { params };

const resp = $.steps.listBookings.response || {};
const bookings = resp.data?.bookings || resp.bookings || resp.data || [];
const list = Array.isArray(bookings) ? bookings : [];
return {
  bookings: list.map(b => ({
    id: b.id,
    uid: b.uid,
    title: b.title,
    startTime: b.startTime,
    endTime: b.endTime,
    status: b.status,
    attendees: (b.attendees || []).map(a => ({ name: a.name, email: a.email }))
  })),
  count: list.length,
  summary: `Found ${list.length} booking${list.length === 1 ? '' : 's'}`
};
